"use client";

import { useState } from "react";
import { initialJawabanSiswa, JawabanSiswaItem } from "@/data/jawabanSiswaData";
import { bankSoalUjian } from "@/data/soalData";
import Link from "next/link";

export default function AdminPenilaianPage() {
  const [daftarJawaban, setDaftarJawaban] = useState<JawabanSiswaItem[]>(initialJawabanSiswa);
  const [selectedSubmission, setSelectedSubmission] = useState<JawabanSiswaItem | null>(
    initialJawabanSiswa[0] || null
  );

  // State untuk nilai per soal yang diinput guru
  const [nilaiInput, setNilaiInput] = useState<{ [key: string]: number }>({});
  const [isSaved, setIsSaved] = useState(false);

  const handleNilaiChange = (key: string, value: number) => {
    setNilaiInput((prev) => ({ ...prev, [key]: value }));
  };

  const hitungTotalNilai = () => {
    let total = 0;
    Object.values(nilaiInput).forEach((val) => {
      total += Number(val) || 0;
    });
    return total;
  };

  const handleSimpanNilai = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSubmission) return;

    const total = hitungTotalNilai();

    // Update status di daftar
    setDaftarJawaban((prev) =>
      prev.map((item) =>
        item.id === selectedSubmission.id
          ? { ...item, status: "Selesai Dinilai", nilaiAkhir: total }
          : item
      )
    );

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  return (
    <main className="min-h-screen bg-gray-100 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto space-y-6">
        
        {/* Header CMS */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-6 rounded-2xl shadow-sm border border-gray-200 gap-4">
          <div>
            <span className="text-xs font-semibold uppercase tracking-wider text-purple-600 bg-purple-50 px-3 py-1 rounded-full">
              Kanal Guru (CMS)
            </span>
            <h1 className="text-2xl font-bold text-gray-900 mt-1">
              Penilaian Ujian Tertulis Siswa 📝
            </h1>
            <p className="text-gray-600 text-sm">
              Periksa dan berikan nilai manual untuk jawaban isian singkat serta essay siswa.
            </p>
          </div>
          <Link
            href="/materi"
            className="text-sm font-medium text-purple-600 hover:underline"
          >
            ← Kembali ke Platform
          </Link>
        </div>

        {/* Layout Utama 2 Kolom */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          
          {/* KOLOM KIRI: Daftar Jawaban Siswa Masuk */}
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-200 space-y-4">
            <h2 className="text-lg font-bold text-gray-900 border-b pb-3">
              Daftar Lembar Jawaban ({daftarJawaban.length})
            </h2>

            <div className="space-y-3">
              {daftarJawaban.map((item) => (
                <div
                  key={item.id}
                  onClick={() => setSelectedSubmission(item)}
                  className={`p-4 rounded-xl border cursor-pointer transition ${
                    selectedSubmission?.id === item.id
                      ? "border-purple-600 bg-purple-50/50 shadow-sm"
                      : "border-gray-200 hover:bg-gray-50"
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <h3 className="font-bold text-gray-900 text-base">{item.namaSiswa}</h3>
                    <span
                      className={`text-xs px-2.5 py-0.5 rounded-full font-medium ${
                        item.status === "Selesai Dinilai"
                          ? "bg-green-100 text-green-700"
                          : "bg-amber-100 text-amber-700"
                      }`}
                    >
                      {item.status}
                    </span>
                  </div>
                  <p className="text-xs text-gray-500">Kelas: {item.kelas}</p>
                  <p className="text-xs text-gray-400 mt-1">Submit: {item.tanggalSubmit}</p>
                  {item.nilaiAkhir !== undefined && (
                    <p className="text-xs font-bold text-purple-700 mt-2">
                      Nilai Akhir: {item.nilaiAkhir} / 100
                    </p>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* KOLOM KANAN: Detail Lembar Pemeriksaan & Input Nilai */}
          <div className="lg:col-span-2 bg-white p-6 sm:p-8 rounded-2xl shadow-sm border border-gray-200 space-y-6">
            {selectedSubmission ? (
              <form onSubmit={handleSimpanNilai} className="space-y-8">
                
                {/* Header Detail Siswa */}
                <div className="flex flex-wrap justify-between items-center border-b pb-4 gap-2">
                  <div>
                    <h2 className="text-xl font-bold text-gray-900">
                      Lembar Jawaban: {selectedSubmission.namaSiswa}
                    </h2>
                    <p className="text-xs text-gray-500 mt-0.5">
                      Kelas {selectedSubmission.kelas} • ID: {selectedSubmission.id}
                    </p>
                  </div>
                  <div className="text-right">
                    <span className="text-xs text-gray-500 block">Total Nilai Saat Ini</span>
                    <span className="text-2xl font-extrabold text-purple-600">
                      {hitungTotalNilai()} <span className="text-xs text-gray-400">/ 100</span>
                    </span>
                  </div>
                </div>

                {isSaved && (
                  <div className="p-4 bg-green-50 border border-green-200 text-green-800 text-sm rounded-xl font-medium">
                    ✅ Nilai berhasil disimpan! Status siswa kini diperbarui.
                  </div>
                )}

                {/* BAGIAN I: PENILAIAN ISIAN SINGKAT (Skor Max: 10 per soal = 50) */}
                <section className="space-y-4">
                  <div className="bg-purple-50 p-3 rounded-xl flex justify-between items-center">
                    <h3 className="font-bold text-purple-900 text-sm">
                       Bagian I — Isian Singkat (Maks. 10 poin / soal)
                    </h3>
                  </div>

                  {bankSoalUjian.isianSingkat.map((soal, idx) => {
                    const jawabanSiswa = selectedSubmission.jawabanIsian[soal.id] || "-";
                    return (
                      <div key={soal.id} className="p-4 bg-gray-50 rounded-xl border border-gray-200 space-y-2">
                        <p className="text-sm font-semibold text-gray-800">
                          {idx + 1}. {soal.question}
                        </p>
                        <div className="p-3 bg-white rounded-lg border border-gray-200">
                          <span className="text-xs text-gray-400 block mb-1">Jawaban Siswa:</span>
                          <p className="text-sm font-medium text-purple-900">{jawabanSiswa}</p>
                        </div>
                        <div className="flex items-center gap-3 pt-1">
                          <label className="text-xs text-gray-600 font-medium">Beri Nilai (0 - 10):</label>
                          <input
                            type="number"
                            min={0}
                            max={10}
                            required
                            placeholder="0"
                            value={nilaiInput[`isian_${soal.id}`] ?? ""}
                            onChange={(e) => handleNilaiChange(`isian_${soal.id}`, Number(e.target.value))}
                            className="w-20 px-3 py-1 bg-white border border-gray-300 rounded-lg text-sm text-center font-bold focus:ring-2 focus:ring-purple-500"
                          />
                        </div>
                      </div>
                    );
                  })}
                </section>

                {/* BAGIAN II: PENILAIAN ESSAY (Skor Max: 10 per soal = 50) */}
                <section className="space-y-4">
                  <div className="bg-purple-50 p-3 rounded-xl flex justify-between items-center">
                    <h3 className="font-bold text-purple-900 text-sm">
                       Bagian II — Uraian / Essay (Maks. 10 poin / soal)
                    </h3>
                  </div>

                  {bankSoalUjian.essay.map((soal, idx) => {
                    const jawabanSiswa = selectedSubmission.jawabanEssay[soal.id] || "-";
                    return (
                      <div key={soal.id} className="p-4 bg-gray-50 rounded-xl border border-gray-200 space-y-2">
                        <p className="text-sm font-semibold text-gray-800">
                          {idx + 1}. {soal.question}
                        </p>
                        <div className="p-3 bg-white rounded-lg border border-gray-200 whitespace-pre-line">
                          <span className="text-xs text-gray-400 block mb-1">Jawaban Uraian Siswa:</span>
                          <p className="text-sm font-medium text-gray-800">{jawabanSiswa}</p>
                        </div>
                        <div className="flex items-center gap-3 pt-1">
                          <label className="text-xs text-gray-600 font-medium">Beri Nilai (0 - 10):</label>
                          <input
                            type="number"
                            min={0}
                            max={10}
                            required
                            placeholder="0"
                            value={nilaiInput[`essay_${soal.id}`] ?? ""}
                            onChange={(e) => handleNilaiChange(`essay_${soal.id}`, Number(e.target.value))}
                            className="w-20 px-3 py-1 bg-white border border-gray-300 rounded-lg text-sm text-center font-bold focus:ring-2 focus:ring-purple-500"
                          />
                        </div>
                      </div>
                    );
                  })}
                </section>

                {/* Tombol Simpan Nilai */}
                <div className="pt-4 border-t flex justify-end">
                  <button
                    type="submit"
                    className="bg-purple-600 hover:bg-purple-700 text-white font-bold px-6 py-3 rounded-xl text-sm transition shadow-sm"
                  >
                    💾 Simpan Nilai Siswa
                  </button>
                </div>

              </form>
            ) : (
              <div className="text-center py-12 text-gray-500">
                Pilih salah satu siswa di sebelah kiri untuk mulai memeriksa jawaban.
              </div>
            )}
          </div>

        </div>
      </div>
    </main>
  );
}